s=s.replace("  } catch (error) {\n    errorMessage.value = getErrorMessage(error, '创建考试失败，请检查试卷、班级与时间窗口');", "  } catch (error) {\n    formErrorMessage.value = getErrorMessage(error, '创建考试失败，请检查试卷、班级与时间窗口');")
