s=s.replace("      <div class=\"section-title\">\n        <div>\n          <h2>考试列表</h2>\n          <p class=\"muted-text\">按考试状态、时间窗口和提交进度快速查看当前账号可管理的考试。</p>\n        </div>\n      </div>", "      <div class=\"section-title\">\n        <div>\n          <h2>考试列表</h2>\n          <p class=\"muted-text\">按考试状态、时间窗口和提交进度快速查看当前账号可管理的考试。</p>\n        </div>\n        <div class=\"section-actions\">\n          <button class=\"secondary-button\" type=\"button\" :disabled=\"loading\" @click=\"loadData\">\n            {{ loading ? '刷新中...' : '刷新列表' }}\n          </button>\n        </div>\n      </div>")
